import 'package:flutter/material.dart';
import '../../models/career.dart';
import '../../services/api_client.dart';
import '../../services/local_vault.dart';
class SurveyScreen extends StatefulWidget{const SurveyScreen({super.key,required this.api,required this.vault});final ApiClient api;final LocalVault vault;@override State<SurveyScreen>createState()=>_SurveyScreenState();}
class _SurveyScreenState extends State<SurveyScreen>{int q1=0,q2=0;String result='';bool busy=false;final q1s=['新しいアイデアを出したり、仕組みを一から構築する時','困っている人を個別でサポートしたり、調整役となる時','黙々とデータ分析や問題改善の作業を進める時'];final q2s=['ワークライフバランスと精神的な穏やかさ','専門スキル習得と成長実感'];Future<void>analyze()async{if(busy)return;setState(()=>busy=true);try{final x=await widget.api.post('/survey/analyze',{'q1':q1s[q1],'q2':q2s[q2]});if(!mounted)return;setState(()=>result=x['text']?.toString()??'');}catch(e){if(mounted)setState(()=>result='診断分析に失敗しました。${e.toString()}');}finally{if(mounted)setState(()=>busy=false);}}Future<void>addToProfile()async{if(result.isEmpty)return;try{final p=ProfileData.fromJson(await widget.api.get('/profile'));final next=(p.freeText.isEmpty?'':'${p.freeText}\n')+'・[診断結果] $result';final np=ProfileData(freeText:next,status:p.status,gender:p.gender,location:p.location,personality:p.personality,relationships:p.relationships,hobbies:p.hobbies,priority:p.priority);await widget.api.put('/profile',np.toJson());await widget.vault.saveProfile(np);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('診断結果をプロフィールに追加しました')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('適性直感診断',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:16),const Text('Q1. チームや職場活動で最もワクワク・貢献感を感じる時は？'),...List.generate(q1s.length,(i)=>RadioListTile(value:i,groupValue:q1,onChanged:(v)=>setState(()=>q1=v!),title:Text(q1s[i]))),const SizedBox(height:8),const Text('Q2. 仕事や進路で重要視したいテーマは？'),...List.generate(q2s.length,(i)=>RadioListTile(value:i,groupValue:q2,onChanged:(v)=>setState(()=>q2=v!),title:Text(q2s[i]))),FilledButton(onPressed:busy?null:analyze,child:Text(busy?'分析中…':'診断結果をAIに分析してもらう')),if(result.isNotEmpty)Card(margin:const EdgeInsets.only(top:16),child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(result),const SizedBox(height:8),OutlinedButton(onPressed:addToProfile,child:const Text('プロフィールに追加'))]))) ]);}
